   "intro": "<p>معايير الاختيار: العمر، القدرة على الفهم، الهدف من الفحص، توفر المعايير، زمن التطبيق. أدوات شائعة في المرجعية الفرنكوفونية: BOT-2، ‏M-ABC-2، اختبارات النغمة (Épreuves de tonus) لأجوريا غيرا (Ajuriaguerra)، اختبار تقليد الإيماءات (Test d'imitation de gestes) لبيرجيس-لازين (Bergès-Lézine)، اختبارات الجانبية (هاريس Harris / زازو Zazzo)، ‏BHK للكتابة، وشبكات ملاحظة حسية-حركية مستلهمة من بولينجر (Bullinger). يُراعى في التوحد تكييف التعليمات (نماذج مصورة، عرض الحركة قبل طلبها).</p>",
