   "intro": "<p>الديسبراكسيا (Dyspraxie) مصطلح تشخيصي (يُسمى أيضًا اضطراب اكتساب التناسق (TAC) في المراجع الفرنسية) لا يحدده المختص النفسي الحركي وحده؛ يشارك فيه فريق متعدد التخصصات. في التوحد قد توجد صعوبات تخطيط دون أن تتحقق معايير هذا التشخيص، ونعبّر عنها وصفيًا: «صعوبات في التخطيط الحركي».</p>",
