   "intro": "<p>عدسة أوسع المميزة: بيلانك لا يُقرأ في فراغ حسي. قبل أن تحسم تفسير أي مكوّن، ضع بجانبه نتائج البروفيل الحسي للمتعلم نفسه (أنماط الاستجابة في المجالات التسعة) واسأل: هل ما أراه صعوبة حركية أصلية، أم تنظيم حسي يتنكر في ثوب حركي؟</p>",
