      "النغمة (Tonus) — الامتداد والانفعالية — نغمة محورية منخفضة، توتر طرفي مرتفع — يحتاج دعمًا",
      "الوضعية (Posture) — الجلوس 5 دقائق — ثبات 3 دقائق ثم انهيار الجذع — يحتاج دعمًا",
