      "المخطط الجسدي (Schéma corporel) — تسمية الأجزاء وتقليد الوضعيات — يسمي 8 أجزاء ويقلد بالصورة — متوسط",
      "التخطيط (Planification) — تسلسل 3 حركات — ينجح بالصور فقط — يحتاج دعمًا",
      "المكاني (Organisation spatiale) — داخل/خارج، فوق/تحت — ينجح في الأساسي دون اليمين/اليسار — متوسط",
